ALTER INDEX index_points_on_user_id RENAME TO points_user_id_custom;
DROP INDEX index_track_segments_on_transportation_mode;
CREATE INDEX index_track_segments_on_transportation_mode ON track_segments (start_index);
CREATE INDEX "idx_points_track_id_timestamp" ON "points" ("track_id", "timestamp");
CREATE INDEX "idx_tracks_user_id_start_at" ON "tracks" ("user_id", "start_at");
DROP INDEX index_points_on_user_id_and_reverse_geocoded_at;
CREATE INDEX index_points_on_user_id_and_reverse_geocoded_at ON points (reverse_geocoded_at, user_id) WHERE reverse_geocoded_at IS NOT NULL;
DROP INDEX index_place_visits_on_visit_id;
CREATE INDEX index_place_visits_on_visit_id ON place_visits (place_id);
